import re

def validate_braces(format_str):
    '''Check that all fields are properly enclosed in matching braces.'''
    # First, identify all field-like substrings (starting with { but not {{)
    # We need to find patterns like {name or {name:... etc.

    # Strategy: find all { that are not preceded by another {
    i = 0
    while i < len(format_str):
        if format_str[i] == '{':
            # Check if next char is also { (escaped brace)
            if i + 1 < len(format_str) and format_str[i+1] == '{':
                i += 2  # Skip {{
                continue

            # This is a potential field start - find the matching }
            j = format_str.find('}', i + 1)
            if j == -1:
                raise ValueError(f\"unclosed field in pattern: {format_str!r}\")
            i = j + 1
        else:
            i += 1

    return True

# Test cases
test_cases = [
    '{name}',           # valid
    '{name',            # invalid - unclosed
    'hello {world}',    # valid  
    'hello {world',     # invalid - unclosed
    '{{name}}',         # valid (escaped braces)
    '{name:width}',     # valid
    '{name:width}',     # valid
    '{}',               # valid (anonymous)
    '{:.2f}',           # valid (anonymous with format)
]

for tc in test_cases:
    try:
        validate_braces(tc)
        print(f'OK: {tc!r}')
    except ValueError as e:
        print(f'ERROR: {tc!r} -> {e}')
